using System;
using System.Linq;
namespace DrawDecks.Domain;
public sealed class ActionResult {public bool Success{get;} public ActionError Error{get;} public MatchState State{get;} internal ActionResult(bool ok,ActionError error,MatchState state){Success=ok;Error=error;State=state;}}
public static class GameEngine {
 public static ActionResult Draw(MatchState state,string playerId,int count=1){if(count<1)throw new ArgumentOutOfRangeException(nameof(count));var err=ValidateTurn(state,playerId);if(err!=ActionError.None)return Fail(state,err);var p=state.CurrentPlayer;if(state.BlockedDrawPlayerId==playerId){state.BlockedDrawPlayerId=null;state.Emit("DrawBlocked",playerId);return Ok(state);}if(p.MutableHand.Count+count>state.Rules.MaximumHandSize)return Fail(state,ActionError.HandLimitReached);if(state.DrawPile.Count<count)return Fail(state,ActionError.DeckEmpty);for(int i=0;i<count;i++)DrawOne(state,p);state.Emit("CardsDrawn",playerId,data:"count="+count);return Ok(state);}
 public static ActionResult PlayCard(MatchState state,string playerId,string cardId,string? targetPlayerId=null,Suit chosenSuit=Suit.None){var err=ValidateTurn(state,playerId);if(err!=ActionError.None)return Fail(state,err);var p=state.CurrentPlayer;var card=p.MutableHand.FirstOrDefault(c=>c.InstanceId==cardId);if(card==null)return Fail(state,ActionError.CardNotInHand);if(card.Definition.Kind==CardKind.Defense)return Fail(state,ActionError.InvalidPhase);if(state.ActiveSuit!=Suit.None&&card.Definition.Kind==CardKind.Standard&&card.Definition.Suit!=state.ActiveSuit)return Fail(state,ActionError.InvalidCardType);if(card.Definition.Effect==CardEffect.Wild&&(chosenSuit==Suit.None||!Enum.IsDefined(typeof(Suit),chosenSuit)))return Fail(state,ActionError.InvalidCardType);var target=targetPlayerId==null?null:state.MutablePlayers.FirstOrDefault(x=>x.Id==targetPlayerId&&!x.IsEliminated);if(targetPlayerId!=null&&(target==null||target.Id==playerId))return Fail(state,ActionError.InvalidTarget);if((IsAttack(card.Definition.Effect)||card.Definition.Effect==CardEffect.SkipTurn||card.Definition.Effect==CardEffect.SwapHands)&&target==null)return Fail(state,ActionError.InvalidTarget);p.MutableHand.Remove(card);state.MutableDiscardPile.Add(card);state.Emit("CardPlayed",playerId,card.InstanceId,targetPlayerId,card.Definition.Effect.ToString());Resolve(state,p,card,target);if(card.Definition.Effect==CardEffect.Wild)state.ActiveSuit=chosenSuit;if(state.PendingAttack==null)Advance(state);CheckVictory(state);return Ok(state);}
 public static ActionResult RespondToAttack(MatchState state,string playerId,string? defenseCardId){if(state.Status!=MatchStatus.Active)return Fail(state,ActionError.MatchNotActive);var attack=state.PendingAttack;if(attack==null||attack.TargetId!=playerId||state.CurrentPlayer.Id!=playerId)return Fail(state,ActionError.InvalidPhase);var defender=state.CurrentPlayer;if(defenseCardId!=null){var defense=defender.MutableHand.FirstOrDefault(c=>c.InstanceId==defenseCardId);if(defense==null)return Fail(state,ActionError.CardNotInHand);if(defense.Definition.Kind!=CardKind.Defense)return Fail(state,ActionError.InvalidDefense);if(defense.Definition.Effect!=CardEffect.Shield&&defense.Definition.Effect!=CardEffect.Negate&&defense.Definition.Effect!=CardEffect.Reflect)return Fail(state,ActionError.InvalidDefense);defender.MutableHand.Remove(defense);state.MutableDiscardPile.Add(defense);if(defense.Definition.Effect==CardEffect.Reflect)ApplyAttack(state,attack.AttackerId,attack.Effect,playerId);state.Emit(defense.Definition.Effect==CardEffect.Reflect?"AttackReflected":"AttackNegated",playerId,defense.InstanceId,attack.AttackerId);}else ApplyAttack(state,attack.TargetId,attack.Effect,attack.AttackerId);state.PendingAttack=null;Advance(state);CheckVictory(state);return Ok(state);}
 public static ActionResult Discard(MatchState state,string playerId,string cardId){var err=ValidateTurn(state,playerId);if(err!=ActionError.None)return Fail(state,err);var p=state.CurrentPlayer;var card=p.MutableHand.FirstOrDefault(c=>c.InstanceId==cardId);if(card==null)return Fail(state,ActionError.CardNotInHand);p.MutableHand.Remove(card);state.MutableDiscardPile.Add(card);state.Emit("CardDiscarded",playerId,card.InstanceId);Advance(state);CheckVictory(state);return Ok(state);}
 public static ActionResult EliminatePlayer(MatchState state,string actorId,string targetPlayerId){var err=ValidateTurn(state,actorId);if(err!=ActionError.None)return Fail(state,err);var target=state.MutablePlayers.FirstOrDefault(p=>p.Id==targetPlayerId&&!p.IsEliminated);if(target==null||target.Id==actorId)return Fail(state,ActionError.InvalidTarget);target.IsEliminated=true;state.Emit("PlayerEliminated",actorId,null,target.Id);CheckVictory(state);if(state.Status==MatchStatus.Active)Advance(state);return Ok(state);}
 public static ActionResult EndTurn(MatchState state,string playerId){var err=ValidateTurn(state,playerId);if(err!=ActionError.None)return Fail(state,err);if(state.PendingAttack!=null)return Fail(state,ActionError.InvalidPhase);Advance(state);CheckVictory(state);return Ok(state);}
 private static void Resolve(MatchState s,PlayerState p,CardInstance c,PlayerState? target){switch(c.Definition.Effect){
 case CardEffect.None:p.Score+=c.Definition.Value*(s.DoubleScoreActive?2:1);s.DoubleScoreActive=false;break;
 case CardEffect.DrawTwo:for(int i=0;i<2&&p.MutableHand.Count<s.Rules.MaximumHandSize&&s.DrawPile.Count>0;i++)DrawOne(s,p);break;
 case CardEffect.SkipTurn:s.SkipPlayerId=target?.Id;s.Emit("TurnSkipped",p.Id,c.InstanceId,target?.Id);break;
 case CardEffect.ReverseOrder:s.Direction*=-1;break;
 case CardEffect.SwapHands:if(target!=null){var temp=p.MutableHand.ToArray();p.MutableHand.Clear();p.MutableHand.AddRange(target.MutableHand);target.MutableHand.Clear();target.MutableHand.AddRange(temp);}break;
 case CardEffect.StealCard:case CardEffect.DiscardRandomCard:case CardEffect.BlockDraw:s.PendingAttack=new PendingAttack(p.Id,target!.Id,c.Definition.Effect,c.InstanceId);s.CurrentPlayerIndex=s.MutablePlayers.IndexOf(target);break;
 case CardEffect.Wild:break;
 case CardEffect.DeckReset:if(s.MutableDiscardPile.Count>0){var recycled=s.MutableDiscardPile.ToList();s.MutableDiscardPile.Clear();DeckBuilder.Shuffle(recycled,NextRandom(s));s.DrawPile.AddRange(recycled);}break;
 case CardEffect.DoubleScore:s.DoubleScoreActive=true;break;
 case CardEffect.Shield:case CardEffect.Reflect:case CardEffect.Negate:break;
 default:throw new InvalidOperationException("Unimplemented effect "+c.Definition.Effect);
 }}
 private static void ApplyAttack(MatchState s,string targetId,CardEffect effect,string attackerId){var target=s.MutablePlayers.First(x=>x.Id==targetId);switch(effect){case CardEffect.StealCard:if(target.MutableHand.Count>0){var card=target.MutableHand[0];target.MutableHand.RemoveAt(0);var attacker=s.MutablePlayers.First(x=>x.Id==attackerId);if(attacker.MutableHand.Count<s.Rules.MaximumHandSize)attacker.MutableHand.Add(card);else s.MutableDiscardPile.Add(card);}break;case CardEffect.DiscardRandomCard:if(target.MutableHand.Count>0){int i=(int)(NextRandom(s)%(ulong)target.MutableHand.Count);var card=target.MutableHand[i];target.MutableHand.RemoveAt(i);s.MutableDiscardPile.Add(card);}break;case CardEffect.BlockDraw: s.BlockedDrawPlayerId=targetId;break;}s.Emit("AttackResolved",attackerId,null,targetId,effect.ToString());}
 private static bool IsAttack(CardEffect e)=>e==CardEffect.StealCard||e==CardEffect.DiscardRandomCard||e==CardEffect.BlockDraw;
 private static void DrawOne(MatchState s,PlayerState p){if(s.DrawPile.Count==0)return;var c=s.DrawPile[0];s.DrawPile.RemoveAt(0);p.MutableHand.Add(c);}
 private static void Advance(MatchState s){if(s.Status!=MatchStatus.Active)return;int index=s.CurrentPlayerIndex;for(int i=0;i<s.MutablePlayers.Count;i++){index=(index+s.Direction+s.MutablePlayers.Count)%s.MutablePlayers.Count;if(!s.MutablePlayers[index].IsEliminated)break;}s.CurrentPlayerIndex=index;if(s.SkipPlayerId==s.CurrentPlayer.Id){s.Emit("TurnSkipped",s.CurrentPlayer.Id);s.SkipPlayerId=null;for(int i=0;i<s.MutablePlayers.Count;i++){index=(index+s.Direction+s.MutablePlayers.Count)%s.MutablePlayers.Count;if(!s.MutablePlayers[index].IsEliminated)break;}s.CurrentPlayerIndex=index;}s.TurnNumber++;s.Emit("TurnStarted",s.CurrentPlayer.Id,data:"turn="+s.TurnNumber);}
 private static void CheckVictory(MatchState s){var alive=s.MutablePlayers.Where(p=>!p.IsEliminated).ToArray();if(alive.Length==1){s.Status=MatchStatus.Completed;s.WinnerPlayerId=alive[0].Id;s.Emit("MatchWon",alive[0].Id);}else if(alive.Length==0){s.Status=MatchStatus.Draw;s.Emit("MatchDraw","system");}else{var leaders=alive.Where(p=>p.Score>=s.Rules.TargetScore).OrderByDescending(p=>p.Score).ToArray();if(leaders.Length>0){s.Status=MatchStatus.Completed;if(leaders.Length>1&&leaders[0].Score==leaders[1].Score){s.Status=MatchStatus.Draw;s.Emit("MatchDraw","system",data:"score-tie");}else{s.WinnerPlayerId=leaders[0].Id;s.Emit("MatchWon",leaders[0].Id,data:"target-score");}}}}
 private static ActionError ValidateTurn(MatchState s,string id){if(s==null)throw new ArgumentNullException(nameof(s));if(s.Status!=MatchStatus.Active)return ActionError.MatchNotActive;if(s.PendingAttack!=null)return ActionError.InvalidPhase;if(s.CurrentPlayer.Id!=id)return s.MutablePlayers.Any(p=>p.Id==id)?ActionError.NotPlayersTurn:ActionError.InvalidPlayer;return ActionError.None;}
 private static ulong NextRandom(MatchState s){ulong x=s.RandomState;x^=x>>12;x^=x<<25;x^=x>>27;s.RandomState=x;return x*2685821657736338717UL;}
 private static ActionResult Ok(MatchState s)=>new(true,ActionError.None,s);private static ActionResult Fail(MatchState s,ActionError e)=>new(false,e,s);
}